// N5 content generated by scripts/ingest/build-n5.ts (validated there and in scripts/validate-content.ts).
// Pack-only words and kanji (content/packs/) resolve through getWord/getKanji too, so SRS, word and kanji pages work for them.
import grammarJson from '../../../content/levels/n5/grammar.json';
import kanjiJson from '../../../content/levels/n5/kanji.json';
import lessonsJson from '../../../content/levels/n5/lessons.json';
import wordsJson from '../../../content/levels/n5/words.json';
import packKanjiJson from '../../../content/packs/kanji.json';
import packsJson from '../../../content/packs/packs.json';
import packWordsJson from '../../../content/packs/words.json';
import type { GrammarPoint, Kanji, Lesson, Pack, Word } from './schemas';

/** N5 words only (quizzes and the mock exam draw from these). */
export const words = wordsJson as Word[];
/** N5 kanji only. */
export const kanjiList = kanjiJson as Kanji[];
export const grammarPoints = grammarJson as GrammarPoint[];
export const lessons = (lessonsJson as Lesson[]).toSorted((a, b) => a.order - b.order);
export const packs = (packsJson as Pack[]).toSorted((a, b) => a.order - b.order);
/** Every word with a page: N5 plus pack-only words. */
export const allWords = [...words, ...(packWordsJson as Word[])];
/** Every kanji with a page: N5 plus pack-only kanji. */
export const allKanji = [...kanjiList, ...(packKanjiJson as Kanji[])];

const wordById = new Map(allWords.map((w) => [w.id, w]));
const kanjiByChar = new Map(allKanji.map((k) => [k.char, k]));
const grammarById = new Map(grammarPoints.map((g) => [g.id, g]));

export const getWord = (id: string) => wordById.get(id);
export const getKanji = (char: string) => kanjiByChar.get(char);
export const getGrammar = (id: string) => grammarById.get(id);
export const getLesson = (id: string) => lessons.find((l) => l.id === id);
export const getPack = (id: string) => packs.find((p) => p.id === id);

/** Lesson slug in URLs is its order ("1".."30"). */
export const lessonByOrder = (order: number) => lessons.find((l) => l.order === order);

export function lessonContent(lesson: Lesson) {
  return {
    words: lesson.wordIds.map((id) => wordById.get(id)!).filter(Boolean),
    kanji: lesson.kanji.map((c) => kanjiByChar.get(c)!).filter(Boolean),
    grammar: lesson.grammarIds.map((id) => grammarById.get(id)!).filter(Boolean),
  };
}

export function packContent(pack: Pack) {
  return {
    words: pack.wordIds.map((id) => wordById.get(id)!).filter(Boolean),
    kanji: pack.kanji.map((c) => kanjiByChar.get(c)!).filter(Boolean),
  };
}

/** Packs that contain a word or kanji, for links back from detail pages. */
export const packsWithWord = (id: string) => packs.filter((p) => p.wordIds.includes(id));
export const packsWithKanji = (char: string) => packs.filter((p) => p.kanji.includes(char));

/** Words that use a kanji, for the kanji detail page. */
export const wordsWithKanji = (char: string) => allWords.filter((w) => w.surface.includes(char));
